cat > /tmp/test-thresholds.mjs << 'EOF'
import { Eval } from './packages/frai-core/src/index.js';
import fs from 'fs';
import os from 'os';
import path from 'path';

// Create test data
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-threshold-test-'));

const outputs = JSON.stringify(['Hello', 'World', 'Test']);
const references = JSON.stringify(['hello', 'world', 'test']);

const outputsPath = path.join(tmpDir, 'outputs.json');
const referencesPath = path.join(tmpDir, 'references.json');

fs.writeFileSync(outputsPath, outputs);
fs.writeFileSync(referencesPath, references);

// Test 1: Without thresholds
console.log('Test 1: Report without thresholds');
const dataset = Eval.loadDataset({ outputsPath, referencesPath });
const evaluations = Eval.runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

const reportNoThresholds = Eval.generateReport({
  evaluations,
  outputsPath,
  referencesPath
});

console.log('Has passed field:', 'passed' in reportNoThresholds);
console.log('Has thresholds field:', 'thresholds' in reportNoThresholds);
console.log('');

// Test 2: With passing thresholds
console.log('Test 2: Report with passing thresholds');
const reportPass = Eval.generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds: { exact_match: 0.9, toxicity: 0.8 }
});

console.log('Passed:', reportPass.passed);
console.log('Thresholds:', JSON.stringify(reportPass.thresholds, null, 2));
console.log('');

// Test 3: With failing thresholds
console.log('Test 3: Report with failing thresholds');
const reportFail = Eval.generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds: { exact_match: 0.99, toxicity: 0.99 }
});

console.log('Passed:', reportFail.passed);
console.log('Thresholds:', JSON.stringify(reportFail.thresholds, null, 2));
console.log('');

// Test 4: With missing metric
console.log('Test 4: Report with missing metric');
const reportMissing = Eval.generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds: { nonexistent_metric: 0.5 }
});

console.log('Passed:', reportMissing.passed);
console.log('Thresholds:', JSON.stringify(reportMissing.thresholds, null, 2));
console.log('');

// Clean up
fs.rmSync(tmpDir, { recursive: true });
console.log('All tests completed successfully!');
EOF
